// UI themes taken from real VS Code color themes. themes.json is generated by scripts/vscode_themes.py; edit the list there.
import THEMES from './themes.json';

export { THEMES };
export const DEFAULT_THEME = 'dark-modern';
export const themeById = id => THEMES.find(t => t.id === id) || THEMES.find(t => t.id === DEFAULT_THEME);

// Set the palette on <html>. index.html replays the saved copy before the app loads, so a reload never flashes another theme.
export function applyTheme(t) {
  const root = document.documentElement;
  for (const [k, v] of Object.entries(t.vars)) root.style.setProperty('--' + k, v);
  root.classList.toggle('light', !t.dark);
  root.style.colorScheme = t.dark ? 'dark' : 'light';
  try { localStorage.setItem('noah.themeVars', JSON.stringify({ dark: t.dark, vars: t.vars })); } catch (e) {}
}
